head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > P > customModelUnFormatter]<br/>바인딩된 DataCollection 에서 선택된 값이 InputBox 에 반영되기 전에 형식을 변환하는 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "화면 로드 시 customModelUnformatter 속성의 사용자 함수가 한번 실행됩니다.",    
        "선택된 DataCollection 값의 형식을 변환하기 위한 사용자 정의 함수를 설정합니다.",
        "사용자 정의 함수의 파라미터로 DataCollection 의 선택값과 현재 컴포넌트에 입력된 값이 전달됩니다.",
        "사용자 정의 함수의 반환값이 InputBox 의 입력값으로 반영됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    gridview1.setFocusedCell(0, 0);
};



scwin.get_text = function(target) {    
    let rtn = '';
    let tagName = target.render.tagName

    if (tagName !== "INPUT") {
        rtn = target.render.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.render.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



scwin.fn_modelunformatter = function (newVal, oldVal) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====unformatter 적용 전=====");        
    // wf_body_bottom.getObj("scwin").setReturnValue("oldValue : " + oldVal);        
    wf_body_bottom.getObj("scwin").setReturnValue("newValue : " + newVal);        

    return newVal + "_CMUF";
}



scwin.gridview1_oncellclick = function (rowIndex, columnIndex, columnId) {    
    wf_body_bottom.getObj("scwin").setReturnValue("=====unformatter 적용 후=====");  
    scwin.get_text(target1);

    let rtn = ''
    rtn = dlt_ref.getRowData(rowIndex)

    wf_body_bottom.getObj("scwin").setReturnValue("바인딩 값 : " + rtn[0]);
};
